var routes=Newtonsoft.Json.Linq.JArray.Parse(System.IO.File.ReadAllText("../production/black-hole-station/v014/civic-streets/routes.json"));
string Path(UnityEngine.Transform t)=>t.parent?Path(t.parent)+"/"+t.name:t.name;
var rows=new System.Collections.Generic.List<object>();
foreach(var route in routes){var ps=((Newtonsoft.Json.Linq.JArray)route["points"]).Select(p=>new UnityEngine.Vector3((float)p[0],0,(float)p[1])).ToArray();var hit=new System.Collections.Generic.HashSet<string>();
 for(int i=1;i<ps.Length;i++){var d=ps[i]-ps[i-1];var side=UnityEngine.Vector3.Cross(d.normalized,UnityEngine.Vector3.up);for(float t=0;t<=d.magnitude;t+=.5f)foreach(float offset in new[]{-1.6f,0,1.6f}){var p=ps[i-1]+d.normalized*t+side*offset;foreach(var c in UnityEngine.Physics.OverlapCapsule(p+UnityEngine.Vector3.up*.5f,p+UnityEngine.Vector3.up*1.6f,.3f))if(c.enabled&&!c.isTrigger)hit.Add(Path(c.transform));}}
 rows.Add(new{name=(string)route["name"],hits=hit.ToArray()});}
return rows;
